using System.Text.Json;
using MagicStatusbarAdapter;
using YoyoClawCompanion.Services;

var checks=0;
void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}
var now=DateTimeOffset.Now;
string Data(DateTimeOffset updated,bool waiting=false,double? quota=50)=>JsonSerializer.Serialize(new{updatedAt=updated,codex=new{running=true,busy=true,requiresConfirmation=waiting,fiveHourRemainingPercent=quota,recentResponseAt=now.AddMinutes(-1)},yoyo=new{running=true,busy=false,points=410,recentResponseAt=now.AddMinutes(-2),result="Full completion body"}});
var initial=StatusModel.Parse(Data(now),now);
Check(initial.Items[0].Value=="5小时 50%","normal quota");
Check(StatusModel.Parse(Data(now,quota:null),now).Items[0].Value=="5小时 —","null quota");
Check(StatusModel.Parse(Data(now.AddSeconds(-46)),now).Items[0].Value=="—","stale quota removed");
Check(StatusModel.Parse(Data(now.AddSeconds(11)),now).Warning!=null,"future snapshot invalid");
Check(StatusModel.Parse(Data(now,waiting:true),now).Items[0].Value=="等待确认","waiting priority");
Check(initial.Items[1].Preview=="Full completion body","completion body available for requested preview");
var layout=CenteredSpan.Calculate(0,3072,156,1926,2);
Check(layout.Center==1536&&layout.Width==692,"true center symmetric bounds");
var crowded=CenteredSpan.Calculate(0,3072,156,1782,2);
Check(crowded.Width==404&&crowded.Center==1536,"shortcut growth reduces width without moving center");
Check(CenteredSpan.Calculate(0,3072,156,1500,2).Width==0,"occupied center cannot overlap controls");
Check(CenteredSpan.Calculate(-1920,1920,-1764,-600,1).Center==-960,"negative monitor center");
var model=new StatusModel();model.Apply(initial,now);Check(model.CurrentNotice==null,"startup completion not replayed");
model.NewSystemNotice("QQ",now,"Sender","First full body","qq-1");
model.NewSystemNotice("QQ",now.AddMilliseconds(50),"Sender","Second full body","qq-2");
Check(model.CurrentNotice?.Count==2&&model.CurrentNotice.Text.Contains("Second full body"),"burst merged with latest text");
Check(model.CurrentNotice!.Expires==now.AddSeconds(8),"burst does not indefinitely extend deadline");
model.NewSystemNotice("Other app",now.AddMilliseconds(100),"Other title","Other body","other-1");
Check(model.PendingCount==1&&model.CurrentNotice.Source=="QQ","other source queued without interruption");
model.NewSystemNotice("QQ",now.AddMilliseconds(150),"Duplicate","Duplicate body","qq-2");Check(model.CurrentNotice.Count==2,"duplicate identity ignored");
Check(model.Expire(now.AddSeconds(8))&&model.CurrentNotice==null,"round ends on deadline with quota break");
Check(model.Expire(now.AddSeconds(10))&&model.CurrentNotice?.Source=="Other app","FIFO next source after break");
model.SetCodexQuestion("ask","Please answer",now.AddSeconds(11));
Check(model.CurrentNotice?.State=="attention"&&model.PendingCount==1,"question prioritizes and pauses notice");
model.Expire(now.AddMinutes(1));Check(model.CurrentNotice!.State=="attention","question not expired by notice clock");
model.SetCodexQuestion(null,null,now.AddMinutes(1));Check(model.CurrentNotice.Source=="Other app"&&model.CurrentNotice.Expires==now.AddMinutes(1).AddSeconds(7),"answer resumes remaining reading time");
model.SetVisible(false,now.AddMinutes(1).AddSeconds(1));model.Expire(now.AddMinutes(3));model.SetVisible(true,now.AddMinutes(3));Check(model.CurrentNotice.Source=="Other app"&&model.CurrentNotice.Expires==now.AddMinutes(3).AddSeconds(6),"smart hide pauses reading timer");
var overflow=new StatusModel();overflow.NewSystemNotice("start",now);for(var i=0;i<20;i++)overflow.NewSystemNotice("app"+i,now,body:"body",key:"overflow"+i);
Check(overflow.PendingCount==13&&overflow.PendingMessages==20&&overflow.OverflowCount==8,"bounded source groups and explicit overflow count");
Check(StatusModel.OneLine("Hello\r\nWorld\tdata",100)=="Hello World data","content is single line");
Check(StatusModel.OneLine(new string('x',100),20).Length==20&&StatusModel.OneLine(new string('x',100),20).EndsWith('…'),"body length bounded");
string Record(object payload,string type="response_item")=>JsonSerializer.Serialize(new{timestamp=DateTimeOffset.UtcNow,type,payload});
string Ask(string id)=>Record(new{type="function_call",name="request_user_input_async",call_id=id,arguments=JsonSerializer.Serialize(new{questions=new[]{new{title="Question"}}})});
string Event(string type)=>Record(new{type},"event_msg");
string Output(string id,object result)=>Record(new{type="function_call_output",call_id=id,output=JsonSerializer.Serialize(result)});
var reader=new CodexDecisionReader();reader.Apply([Ask("a"),Output("a",new{accepted=true})],"session");Check(reader.Current!=null,"accepted delivery remains pending");
reader.Apply([Event("task_complete")],"session");Check(reader.Current==null,"completed turn clears pending");
reader.Apply([Ask("b"),Event("turn_aborted")],"session");Check(reader.Current==null,"aborted turn clears pending");
reader.Apply([Ask("c"),Output("c",new{answers=new{q="yes"}})],"session");Check(reader.Current==null,"actual answer clears pending");
reader.Apply(["malformed",Ask("d")],"session");Check(reader.Current!=null,"malformed unrelated record tolerated");
var replyText="<send_user_message_question_reply>"+JsonSerializer.Serialize(new[]{new{questionItemId=JsonSerializer.Serialize(new object[]{"request_user_input_async","d",0}),answer="done"}})+"</send_user_message_question_reply>";
reader.Apply([Record(new{type="message",role="user",content=new[]{new{type="input_text",text=replyText}}})],"session");Check(reader.Current==null,"async user answer clears pending");
var dbAt=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
var questionJson=JsonSerializer.Serialize(new{type="agentMessage",phase="final_answer",questions=new[]{new{title="First question"},new{title="Second question"}}});
HistoryItem DbAnswer(int index)=>new("thread","turn","answer"+index,dbAt+index+1,"userMessage",JsonSerializer.Serialize(new{content=new[]{new{type="text",text="<send_user_message_question_reply>"+JsonSerializer.Serialize(new[]{new{questionItemId=JsonSerializer.Serialize(new object[]{"request_user_input_async","dbcall",index}),answer="done"}})+"</send_user_message_question_reply>"}}}));
var dbAsk=new HistoryItem("thread","turn","dbcall",dbAt,"agentMessage",questionJson);
Check(PaginatedCodexObserver.ReadQuestions([dbAsk],new(){"thread|turn"}).Count==1,"paginated question card despite final phase");
Check(PaginatedCodexObserver.ReadQuestions([dbAsk,DbAnswer(0)],new(){"thread|turn"}).Count==1,"paginated partial answer keeps second question");
Check(PaginatedCodexObserver.ReadQuestions([dbAsk,DbAnswer(0),DbAnswer(1)],new(){"thread|turn"}).Count==0,"paginated all answers clear pending");
Check(PaginatedCodexObserver.ReadQuestions([dbAsk],new()).Count==0,"completed turn cannot retain question card");
Console.WriteLine($"PASS {checks} layout, notification queue, privacy and Codex lifecycle checks");
Check(Math.Abs(TextPulse.Factor(0)-1)<0.001,"pulse full brightness");
Check(Math.Abs(TextPulse.Factor(350)-0.12)<0.001,"pulse strengthened minimum");
Check(Math.Abs(TextPulse.Factor(700)-1)<0.001,"faster pulse period");
Check(Enumerable.Range(0,700).All(i=>TextPulse.Factor(i)>=0.119&&TextPulse.Factor(i)<=1.001),"pulse opacity bounded");
Console.WriteLine($"PASS {checks} total checks including strengthened text pulse");
var deepJson=JsonSerializer.Serialize(new{updatedAt=now,deepSeek=new{IsRunning=true,Available=true,State="idle"}});
var ds=StatusModel.Parse(deepJson,now).Items.Single();Check(ds.Name=="DeepSeek Harness"&&ds.Value=="空闲","DeepSeek snapshot recognized without fake quota");
var decisionJson=JsonSerializer.Serialize(new{updatedAt=now,deepSeek=new{IsRunning=true,Available=true,State="decision"}});
Check(StatusModel.Parse(decisionJson,now).Items.Single().Status=="attention","DeepSeek decision state preserved");
var stoppedJson=JsonSerializer.Serialize(new{updatedAt=now,deepSeek=new{IsRunning=false,Available=true,State="idle"}});
Check(!StatusModel.Parse(stoppedJson,now).Items.Any(i=>i.Name=="DeepSeek Harness"),"closed DeepSeek removed");
Check(ProviderLabels.Short("Codex")=="Codex","Codex unchanged");Check(ProviderLabels.Short("WorkBuddy")=="WB","WorkBuddy short label");Check(ProviderLabels.Short("YOYO")=="YOYO","YOYO unchanged");Check(ProviderLabels.Short("DeepSeek Harness")=="DSH","DeepSeek short label");
var map=new InteractionMap();map.Areas.Add(new(new System.Drawing.RectangleF(10,6,100,52),"Codex"));map.Areas.Add(new(new System.Drawing.RectangleF(130,6,100,52),"DeepSeek Harness"));
Check(map.Find(new System.Drawing.Point(20,32))?.Provider=="Codex","first provider hit");Check(map.Find(new System.Drawing.Point(200,32))?.Provider=="DeepSeek Harness","DeepSeek provider hit");Check(map.Find(new System.Drawing.Point(120,32))==null,"gap remains mouse-through");Check(map.Find(new System.Drawing.Point(20,0))==null,"empty vertical margin remains mouse-through");
Console.WriteLine($"PASS {checks} total checks including provider recognition, labels and mouse regions");
var grouped=new StatusModel();grouped.NewSystemNotice("OPPO 互联",now,body:"first",key:"g0");grouped.NewSystemNotice("Other",now,body:"other",key:"other");
for(var i=1;i<6;i++)grouped.NewSystemNotice("OPPO 互联",now.AddSeconds(i),body:"latest"+i,key:"g"+i);
Check(grouped.CurrentNotice?.Count==6&&grouped.PendingCount==1,"continuous same-source arrivals form one round");
Check(grouped.CurrentNotice!.Expires==now.AddSeconds(8)&&grouped.CurrentNotice.Text=="latest5","continuous arrivals preserve deadline and latest content");
grouped.SetCodexQuestion("wait","answer",now.AddSeconds(6));grouped.NewSystemNotice("OPPO 互联",now.AddSeconds(7),body:"while waiting",key:"g7");
Check(grouped.PendingCount==2,"paused same-source merges instead of creating third group");
grouped.SetCodexQuestion(null,null,now.AddSeconds(10));Check(grouped.CurrentNotice?.Count==7&&grouped.CurrentNotice.Text=="while waiting","paused group latest content survives");
var waitingGroups=new StatusModel();waitingGroups.SetVisible(false,now);
for(var i=0;i<30;i++)waitingGroups.NewSystemNotice("One app",now.AddSeconds(i),body:"body"+i,key:"hidden"+i);
Check(waitingGroups.PendingCount==1&&waitingGroups.PendingMessages==30,"hidden backlog counted by source");
waitingGroups.SetVisible(true,now.AddSeconds(40));Check(waitingGroups.CurrentNotice?.Count==30&&waitingGroups.CurrentNotice.Text=="body29","hidden group displays latest once");
Check(CenteredSpan.Calculate(0,3072,457,2070,2).Width==980,"fixed-mode AI recommendation left occupancy preserves center");
Console.WriteLine($"PASS {checks} total checks including continuous source grouping and fixed-mode regression");

var configured=new StatusModel{RoundSeconds=3};configured.NewSystemNotice("App",now,body:"first",key:"configured");
Check(configured.CurrentNotice!.Expires==now.AddSeconds(3),"configured source round duration");
configured.SetVisible(false,now.AddSeconds(1));configured.NewSystemNotice("App",now.AddSeconds(2),body:"latest",key:"configured2");
configured.SetVisible(true,now.AddSeconds(20));Check(configured.CurrentNotice!.Expires==now.AddSeconds(22)&&configured.CurrentNotice.Count==2,"configured round survives hidden coalescing");
var identity=new StatusModel();identity.NewSystemNotice("QQ",now,"first","body","message-1","QQ.App");
Check(identity.CurrentNotice!.AppId=="QQ.App","system notice preserves validated activation identity");
var round=identity.CurrentNotice.Key;identity.NewSystemNotice("QQ",now.AddSeconds(1),"latest","body2","message-2","QQ.Latest");
Check(identity.CurrentNotice.Key==round&&identity.CurrentNotice.AppId=="QQ.Latest","source merge preserves round and latest app target");
Check(!identity.Feedback(round,"message-1","old failure"),"stale activation cannot replace newer notification content");
Check(identity.Feedback(round,"message-2","unable to open")&&identity.CurrentNotice.Source=="QQ"&&identity.CurrentNotice.Text=="unable to open","feedback replaces only content and retains source");
Check(identity.CurrentNotice.Expires==now.AddSeconds(8),"feedback does not extend notification round");
identity.SetCodexQuestion("ask","pending",now.AddSeconds(2));
Check(identity.Feedback(round,"message-2","while pending"),"activation feedback updates paused round without stealing priority");
Check(identity.CurrentNotice.Source=="Codex","pending question remains priority during activation");
identity.SetCodexQuestion(null,null,now.AddSeconds(3));Check(identity.CurrentNotice.Source=="QQ"&&identity.CurrentNotice.Text=="while pending","resume retains source and launch feedback");
Check(identity.Dismiss(round,"message-2",now.AddSeconds(4))&&identity.CurrentNotice==null,"successful activation dismisses current source round");
var slow=new StatusModel();slow.NewSystemNotice("App",now,body:"body",key:"slow",appId:"App.Id");slow.BeginOpen("slow",now.AddSeconds(7));slow.Expire(now.AddSeconds(20));
Check(slow.CurrentNotice?.Source=="App","slow app activation keeps source displayed beyond original countdown");slow.EndOpen(now.AddSeconds(20));slow.Feedback("slow","slow","failed");Check(slow.CurrentNotice!.Expires==now.AddSeconds(23),"failed activation leaves a readable feedback interval");
var recover=new LayoutRecovery();Check(recover.Retain(true,true,0),"retain valid layout during first transient UIA failure");Check(recover.Retain(true,true,200),"bounded tray update retains layout");Check(!recover.Retain(true,true,251),"persistent layout failure cannot retain stale geometry indefinitely");recover.Valid();Check(recover.Retain(true,true,500),"successful sample resets failure window");Check(!recover.Retain(true,false,501),"actual smart hide or fullscreen has no recovery delay");Check(!recover.Retain(false,true,502),"startup cannot invent missing layout");
Console.WriteLine($"PASS {checks} integrated model, launch identity and layout recovery checks");

var stamp=new RenderStamp();Check(stamp.Changed(initial,null,980,64,2,0),"first visual renders");
Check(!stamp.Changed(initial,null,980,64,2,0),"unchanged visual skips render");
var metadata=new Snapshot(initial.Items.Select(i=>i with{CompletedAt=now.AddHours(1),Preview="new body"}).ToList(),initial.Warning);
Check(!stamp.Changed(metadata,null,980,64,2,0),"nonvisual bodies and dates skip render");
Check(stamp.Changed(metadata with{Items=metadata.Items.Select(i=>i with{Value=i.Value+"1"}).ToList()},null,980,64,2,0),"quota changes repaint");
var noticeCache=new Notice("QQ","body","notification",now.AddSeconds(8),AppId:"QQ.App",Title:"raw title");
Check(stamp.Changed(initial,noticeCache,980,64,2,0),"notification renders");
Check(!stamp.Changed(initial,noticeCache with{Expires=now.AddSeconds(30)},980,64,2,0),"expiry alone does not allocate pixels");
Check(stamp.Changed(initial,noticeCache with{Title="different raw title"},980,64,2,0),"mute action identity invalidates cache");
foreach(var width in new[]{80,160,404,980}){
 var geo=NotificationGeometry.Calculate(width,2,140);
 Check(geo.TextWidth>0&&geo.ButtonLeft>=geo.TextWidth&&geo.ButtonLeft+geo.ButtonWidth<=width,"mute geometry stays in safe span "+width);
 Check((width-geo.TextWidth)/2+geo.TextWidth<geo.ButtonLeft,"centered text cannot collide with far-right mute "+width);
}
Check(StatusPainter.Numeric('5')&&StatusPainter.Numeric('.')&&StatusPainter.Numeric('%')&&!StatusPainter.Numeric('小'),"digits and numeric punctuation use bold face");
var raw=new string('标',100);var ignored=new StatusModel();ignored.NewSystemNotice(new string('源',100),now,raw,"body","raw1","App.Id");
Check(ignored.CurrentNotice!.Title==raw&&ignored.CurrentNotice.OriginalSource?.Length==100,"mute preserves full original title and source");
ignored.NewSystemNotice("Other",now,raw,"body","raw2","Other.Id");ignored.RemoveIgnored("App.Id",raw,now);
Check(ignored.CurrentNotice==null&&ignored.PendingCount==1,"mute removes matching active group only");
ignored.Expire(now.AddSeconds(2));Check(ignored.CurrentNotice!.Source=="Other","unrelated source resumes normally after mute");
ignored.SetCodexQuestion("priority","answer",now.AddSeconds(3));ignored.RemoveIgnored("Other.Id",raw,now.AddSeconds(3));
Check(ignored.CurrentNotice.Source=="Codex"&&ignored.PendingCount==0,"mute also removes matching paused groups without replacing question");
using(var painter=new StatusPainter()){
 using var rendered=painter.Paint(initial,noticeCache with{Text=new string('长',200)},404,64,2,0).Pixels;
 Check(rendered.Width==404&&rendered.Height==64,"notification renders full safe span for centered text and mute");
 var frame=painter.Paint(initial,noticeCache,980,64,2,0);
 Check(frame.Hits.Areas.Count(a=>a.Action==HitAction.Mute)==1,"system notification has one mute target");
 var muteArea=frame.Hits.Areas.Single(a=>a.Action==HitAction.Mute);
 Check(frame.Hits.Find(new System.Drawing.Point((int)(muteArea.Bounds.Left+muteArea.Bounds.Width/2),32))?.Action==HitAction.Mute,"far-right mute target does not activate app content");frame.Pixels.Dispose();
 var ai=painter.Paint(initial,new Notice("Codex","answer","attention",DateTimeOffset.MaxValue),980,64,2,0);
 Check(ai.Hits.Areas.All(a=>a.Action!=HitAction.Mute),"Codex decision has no system mute action");ai.Pixels.Dispose();
}
Console.WriteLine($"PASS {checks} total including visual caching, numeric typography and shared mute identity");

Check(NotificationAppearance.MuteRadius(24,24)==6&&NotificationAppearance.MuteRadius(2,24)==2&&NotificationAppearance.MuteRadius(0,24)==0,"normal and Magic reuse compact button radius calculation");
using(var roundPainter=new StatusPainter()){
 var frame=roundPainter.Paint(initial,noticeCache,980,64,2,0);
 var action=frame.Hits.Areas.Single(a=>a.Action==HitAction.Mute).Bounds;
 Check(frame.Pixels.GetPixel((int)action.Left,(int)action.Top).A==0,"mute button corners are transparent and rounded");frame.Pixels.Dispose();
}
Console.WriteLine($"PASS {checks} including reused notification button corners");
